// --- Toast Notification ---
export interface ToastMessage {
    message: string;
    type: 'success' | 'error' | 'info';
}

export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => {
        if (toast) {
            setVisible(true);
            const timer = setTimeout(() => {
                setVisible(false);
                setTimeout(onClose, 300); // Wait for animation
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [toast, onClose]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-gray-900 text-white',
        error: 'bg-red-500 text-white',
        info: 'bg-blue-500 text-white'
    };

    return (
        <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[100] transition-all duration-500 ease-in-out ${visible ? 'translate-y-0 opacity-100' : '-translate-y-8 opacity-0'}`}>
            <div className={`flex items-center gap-3 px-6 py-3 rounded-full shadow-2xl ${colors[toast.type]} min-w-[200px] max-w-xs`}>
                <i className={`fa-solid fa-${icons[toast.type]}`}></i>
                <span className="text-sm font-bold tracking-wide">{toast.message}</span>
            </div>
        </div>
    );
};

// --- Modal ---
export const Modal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    title: string; 
    children: React.ReactNode; 
    maxWidth?: string 
}> = ({ isOpen, onClose, title, children, maxWidth = 'max-w-md' }) => {
    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-gray-900/50 backdrop-blur-sm" onClick={onClose}></div>
            <div className={`relative bg-white rounded-3xl shadow-2xl w-full ${maxWidth} overflow-hidden flex flex-col max-h-[90vh] animate-slide-up`}>
                <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-white sticky top-0 z-10">
                    <h3 className="text-lg font-bold font-display text-gray-900">{title}</h3>
                    <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center hover:bg-gray-100 transition-colors">
                        <i className="fa-solid fa-xmark text-gray-500"></i>
                    </button>
                </div>
                <div className="p-6 overflow-y-auto custom-scrollbar">
                    {children}
                </div>
            </div>
        </div>
    );
};

// --- Toggle Switch ---
