    const [contactForm, setContactForm] = useState({ fullName: currentUser?.name || '', email: currentUser?.email || '', message: '' });
    const [regStatus, setRegStatus] = useState<'idle'|'submitting'>('idle');

    if (!currentUser) return <div className="p-10 text-center">Loading Profile...</div>;

    // -- Derived Data --
    const myVendorProfile = vendors.find(v => v.userId === currentUser.id);
    const myDeliveryProfile = deliveryPersons.find(d => d.userId === currentUser.id);
    const myOrders = orders.filter(o => o.buyerId === currentUser.id).sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    const vendorOrders = orders.filter(o => o.vendorId === myVendorProfile?.vendorId);

    const formatDate = (dateStr: string) => new Date(dateStr).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });

    // -- Handlers --
    const handleRoleSwitch = (role: 'buyer' | 'vendor' | 'deliveryPerson') => {
        if (role === 'deliveryPerson' && (!myDeliveryProfile || myDeliveryProfile.status !== 'approved')) {
            showToast("Delivery account not active", "error");
            return;
        }
        switchRole(role);
        if (role === 'buyer') navigate('/buyer/dashboard');
        if (role === 'vendor') navigate('/vendor/dashboard');
        if (role === 'deliveryPerson') navigate('/delivery/dashboard');
    };

    const handleDeliverySubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!deliveryForm.agreed) return alert("Please agree to terms.");
        setRegStatus('submitting');

        try {
            await registerDeliveryPerson({
                fullName: deliveryForm.fullName,
                vehicleType: deliveryForm.transportType.toLowerCase(),
                transportType: deliveryForm.transportType as any,
                deliveryRadius: deliveryForm.radius,
            });
            setIsDeliveryRegOpen(false);
        } catch (error) {
            showToast("Registration failed.", "error");
        } finally {
            setRegStatus('idle');
        }
    };

    const handleContactSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setRegStatus('submitting');
        const success = await submitContactMessage(contactForm);
        setRegStatus('idle');
        if (success) setIsContactOpen(false);
    };

    const handleDeleteAccount = () => {
        setIsDeleteModalOpen(false);
        showToast("Account deletion request received.", "info");
        logout();
        navigate('/');
    };

    // 1. User Info Section (Universal)
    const renderUserInfo = () => (
        <Card className="p-6 mb-6">
            <div className="flex flex-col md:flex-row items-center gap-6">
                <div className="relative group cursor-pointer" onClick={() => showToast("Edit photo functionality coming soon", "info")}>
                    <Avatar src={currentUser.avatarUrl} name={currentUser.name} size="2xl" className="border-4 border-gray-50 shadow-sm" overlayIcon="camera" />
                </div>
                <div className="flex-1 text-center md:text-left space-y-1">
                    <h2 className="text-2xl font-bold text-gray-900">{currentUser.name}</h2>
                    <p className="text-gray-500 font-medium">{currentUser.email}</p>
                    <div className="flex items-center justify-center md:justify-start gap-2 text-sm text-gray-500">
                         <span>{currentUser.phoneNumber || '+233 20 000 0000'}</span>
                         <Badge color="green" className="py-0 px-1.5 text-[9px]">Verified</Badge>
                    </div>
                    <div className="flex items-center justify-center md:justify-start gap-2 text-sm text-gray-500 pt-1">
                         <i className="fa-solid fa-location-dot text-gray-400"></i>
                         <span>{currentUser.defaultLocation || 'University Campus, Legon'}</span>
                         <button className="text-primary text-xs font-bold hover:underline">Update</button>
                    </div>
                </div>
                <div className="flex flex-col gap-3 w-full md:w-auto">
                    <Button variant="outline" size="sm" onClick={() => setIsEditProfileOpen(true)}>Edit Profile</Button>
                    <Button variant="ghost" size="sm" onClick={() => showToast("Password change email sent", "success")}>Change Password</Button>
                </div>
            </div>
        </Card>
    );

    // 2. Buyer Mode Specifics
    const renderBuyerSection = () => (
        <div className="animate-fade-in space-y-6">
