                <Button size="sm" onClick={() => navigate('/buyer/dashboard')}>Open Shop</Button>
            </div>

            <Card className="p-6">
                <div className="flex justify-between items-center mb-4">
                    <h4 className="font-bold text-gray-800">Recent Orders</h4>
                    <button className="text-primary text-xs font-bold" onClick={() => navigate('/buyer/orders')}>View All</button>
                </div>
                {myOrders.slice(0, 3).map(order => (
                    <div key={order.id} className="py-3 border-b border-gray-50 last:border-0 flex justify-between items-center cursor-pointer hover:bg-gray-50 px-2 -mx-2 rounded" onClick={() => setTrackingOrder(order)}>
                        <div className="flex gap-3">
                            <div className="w-10 h-10 bg-indigo-50 rounded-lg flex items-center justify-center text-primary"><i className="fa-solid fa-box"></i></div>
