            </Card>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Card className="p-6 flex flex-col justify-between">
                    <div>
                        <h4 className="font-bold text-gray-800 mb-2">Saved Vendors</h4>
                        <p className="text-xs text-gray-400 mb-4">Quick access to your favorite stores.</p>
                    </div>
                    <Button variant="outline" size="sm" fullWidth>View Vendors</Button>
                </Card>
                <Card className="p-6 flex flex-col justify-between">
                    <div>
                        <h4 className="font-bold text-gray-800 mb-2">Wishlist</h4>
                        <p className="text-xs text-gray-400 mb-4">Items you've saved for later.</p>
                    </div>
                    <Button variant="outline" size="sm" fullWidth onClick={() => navigate('/buyer/wishlist')}>View Wishlist</Button>
                </Card>
            </div>
        </div>
    );

    // 3. Vendor Mode Specifics
    const renderVendorSection = () => {
