                <Card className="p-6">
                    <div className="flex flex-col md:flex-row gap-6">
                        <div className="w-24 h-24 bg-gray-100 rounded-2xl overflow-hidden flex-shrink-0 border border-gray-200 relative group">
                            <img src={myVendorProfile.storeAvatarUrl || 'https://via.placeholder.com/100'} className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-xs font-bold cursor-pointer transition-opacity">Edit Logo</div>
