                    <div>
                         <h1 className="text-xl font-display font-bold text-gray-900">Profile</h1>
                         <p className="text-[10px] text-gray-400 font-medium tracking-wide">Where Buyers and Sellers Get <span className="text-primary">LYNQED</span>.</p>
                    </div>
                    {/* Desktop Shortcuts */}
                    <div className="hidden lg:flex items-center gap-4">
                        <Button variant="ghost" size="sm" icon="cart-shopping" onClick={() => navigate('/buyer/cart')}>Cart</Button>
                        <Button variant="ghost" size="sm" icon="box" onClick={() => navigate('/buyer/orders')}>Orders</Button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
