import { Order, OrderStatus } from '../types';

// --- Order Tracking Component ---
const OrderTracking: React.FC<{ order: Order; onClose: () => void }> = ({ order, onClose }) => {
    const isPickup = order.deliveryOption === 'pickup';

    // Define Flow Steps
    const deliverySteps = [
        { key: 'placed', label: 'Order Placed' },
        { key: 'received', label: 'Order Received' }, 
        { key: 'in_route', label: 'Delivery En Route' },
        { key: 'delivered', label: 'Delivered' }
    ];

    const pickupSteps = [
        { key: 'placed', label: 'Order Placed' },
        { key: 'received', label: 'Order Received' },
        { key: 'ready_for_pickup', label: 'Order Ready for Pickup' },
        { key: 'delivered', label: 'Completed' }
    ];

    const steps = isPickup ? pickupSteps : deliverySteps;

    const getStepIndex = (status: OrderStatus) => {
        if (status === 'placed') return 0;
        if (['received', 'preparing', 'assigned'].includes(status)) return 1;
        if (['ready_for_pickup', 'picked_up', 'in_route'].includes(status)) return 2;
        if (['delivered', 'completed'].includes(status)) return 3;
        return 0;
    };

    const activeIndex = getStepIndex(order.status);
    const isFailed = ['declined', 'cancelled'].includes(order.status);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center mb-6 bg-gray-50 p-4 rounded-2xl">
                <div>
                     <p className="text-xs font-bold text-gray-400 uppercase">Order ID</p>
                     <p className="font-mono font-bold text-lg">#{order.id.slice(-5)}</p>
                </div>
                <div className="text-right">
                     <p className="text-xs font-bold text-gray-400 uppercase">Total</p>
                     <p className="font-bold text-lg text-primary">₵{order.total.toFixed(2)}</p>
                </div>
            </div>

            {isFailed ? (
                <div className="p-4 bg-red-50 text-red-600 rounded-xl text-center font-bold">
                    Order {order.status}
                </div>
            ) : (
                <div className="relative pl-4 border-l-2 border-gray-100 space-y-8 my-8 ml-2">
                    {steps.map((step, idx) => {
                        const isActive = idx === activeIndex;
                        const isCompleted = idx < activeIndex;

                        return (
                            <div key={step.key} className="relative pl-6">
                                <div className={`absolute -left-[9px] top-1 w-4 h-4 rounded-full border-2 transition-all ${isCompleted || isActive ? 'bg-primary border-primary' : 'bg-white border-gray-300'}`}></div>

                                <h4 className={`font-bold text-sm ${isActive || isCompleted ? 'text-gray-900' : 'text-gray-400'}`}>{step.label}</h4>
                                {isActive && (
                                    <div className="mt-1 animate-fade-in">
                                        <p className="text-xs text-primary font-medium flex items-center gap-1">
                                            <i className="fa-solid fa-clock"></i> {new Date(order.createdAt).toUTCString().slice(0, 22)}
                                        </p>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {order.deliveryPersonId && (
                <div className="bg-blue-50 p-4 rounded-xl flex items-center justify-between border border-blue-100">
                    <div className="flex items-center gap-3">
                         <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-600">
                             <i className="fa-solid fa-motorcycle"></i>
                         </div>
                         <div>
                             <p className="text-xs font-bold text-blue-400 uppercase">Rider</p>
                             <p className="font-bold text-gray-900">Delivery Partner</p>
                         </div>
                    </div>
                    <Button size="sm" variant="outline" icon="phone" onClick={() => alert("Calling rider...")}>Contact</Button>
                </div>
            )}

            <div className="pt-4 border-t border-gray-100 flex justify-between items-center">
                <button className="text-xs font-bold text-gray-400 hover:text-gray-600">Report an issue</button>
                <Button onClick={onClose}>Close</Button>
            </div>
        </div>
    );
};

