    );

    // 6. Role Management Section
    const renderRoleManagement = () => (
        <Card className="p-6 mb-6">
            <h3 className="text-lg font-bold font-display text-gray-900 mb-4">Role Management</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {/* Buyer Role */}
                <div 
                    onClick={() => handleRoleSwitch('buyer')}
                    className={`cursor-pointer rounded-xl p-4 border-2 transition-all flex flex-col items-center justify-center gap-2 ${currentRole === 'buyer' ? 'border-primary bg-primary/5' : 'border-gray-100 hover:border-gray-200'}`}
                >
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${currentRole === 'buyer' ? 'bg-primary text-white' : 'bg-gray-100 text-gray-400'}`}>
