Here is the updated SQL script that fixes the error by checking if policies exist before creating them (idempotent), and adds the new `contact_messages` table.

I have also updated `context.tsx` to handle the Theme Toggle and Contact Form logic, and completely rewrote `pages/Profile.tsx` to match your detailed specification.

### 1. SQL Script (Copy & Run in Supabase SQL Editor)
This script is safe to run multiple times; it drops old policies before recreating them to avoid the "already exists" error.

```sql
-- 1. Enable UUID extension
create extension if not exists "uuid-ossp";

-- 2. Create Tables (Safe if they exist)
create table if not exists public.profiles (
  id uuid references auth.users on delete cascade primary key,
  email text,
  name text,
  avatar_url text,
  roles text[] default '{buyer}', 
  default_location text,
  phone_number text,
  is_banned boolean default false,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

create table if not exists public.vendors (
  id uuid default uuid_generate_v4() primary key,
  vendor_id text unique not null,
  user_id uuid references public.profiles(id),
  store_name text,
  store_description text,
  store_avatar_url text,
  location text,
  contact_phone text,
  is_approved boolean default false,
  rating numeric default 5.0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

create table if not exists public.products (
  id uuid default uuid_generate_v4() primary key,
  vendor_id text references public.vendors(vendor_id),
  title text,
  description text,
  price numeric,
  currency text default 'GHS',
  category text,
  images text[],
  stock integer default 0,
  status text default 'pending',
  location text,
  contact_phone text,
  rating numeric default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

create table if not exists public.delivery_persons (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references public.profiles(id),
  full_name text,
  vehicle_type text,
  transport_type text,
  delivery_radius integer,
  status text default 'pending',
  total_deliveries integer default 0,
  rating numeric default 5.0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

create table if not exists public.orders (
  id uuid default uuid_generate_v4() primary key,
  buyer_id uuid references public.profiles(id),
  vendor_id text,
  delivery_person_id uuid references public.profiles(id),
  items jsonb,
  total numeric,
  delivery_fee numeric default 0,
  status text default 'placed', 
  delivery_option text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- New Table for Contact Form
create table if not exists public.contact_messages (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references public.profiles(id), -- Nullable for guests
  full_name text,
  email text,
  message text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 3. Enable RLS
alter table public.profiles enable row level security;
alter table public.vendors enable row level security;
alter table public.products enable row level security;
alter table public.orders enable row level security;
alter table public.delivery_persons enable row level security;
alter table public.contact_messages enable row level security;

-- 4. Helper Function
create or replace function public.is_admin()
returns boolean as $$
select exists (
  select 1 from public.profiles
  where id = auth.uid() and 'admin' = any(roles)
);
$$ language sql security definer;

-- 5. Drop Existing Policies to Avoid Errors
drop policy if exists "Public profiles are viewable by everyone" on public.profiles;
drop policy if exists "Users can insert their own profile" on public.profiles;
drop policy if exists "Users can update own profile" on public.profiles;

drop policy if exists "Vendors viewable by everyone" on public.vendors;
drop policy if exists "Users can register as vendor" on public.vendors;
drop policy if exists "Owners can update vendor" on public.vendors;
drop policy if exists "Admins can update vendors" on public.vendors;

