                        <button className="text-xs text-blue-500 font-bold mt-2 hover:underline" onClick={() => navigate('/delivery/dashboard')}>View Jobs</button>
                    </Card>
                    <Card className="p-4 border-l-4 border-green-500">
                         <p className="text-xs font-bold text-gray-400 uppercase">Earnings</p>
                         <h2 className="text-2xl font-bold text-gray-900 mt-1">₵{(history.length * 10).toFixed(2)}</h2>
                         <button className="text-xs text-green-500 font-bold mt-2 hover:underline" onClick={() => setIsPayoutModalOpen(true)}>Wallet</button>
                    </Card>
                </div>

                <Card className="p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h4 className="font-bold text-gray-800">Payout Methods</h4>
                        <Button size="sm" variant="outline" onClick={() => setIsPayoutModalOpen(true)}>Request Payout</Button>
                    </div>
                    <div className="space-y-3">
                         <div className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                             <div className="flex items-center gap-3">
                                 <i className="fa-solid fa-building-columns text-gray-400"></i>
                                 <span className="text-sm font-medium">MTN MoMo (***890)</span>
                             </div>
                             <span className="text-xs font-bold text-green-600">Primary</span>
                         </div>
                    </div>
                </Card>
            </div>
        );
    };

    // 5. App Info Section
    const renderAppInfo = () => (
        <Card className="p-6 mb-6">
            <h3 className="text-lg font-bold font-display text-gray-900 mb-4">About LYNQED</h3>
            <div className="space-y-1 divide-y divide-gray-50">
                <div onClick={() => setIsContactOpen(true)} className="flex justify-between items-center py-4 cursor-pointer hover:bg-gray-50 px-2 -mx-2 rounded">
                    <span className="text-sm font-medium text-gray-700">Contact Us</span>
                    <i className="fa-solid fa-chevron-right text-xs text-gray-400"></i>
                </div>
                <div className="flex justify-between items-center py-4 cursor-pointer hover:bg-gray-50 px-2 -mx-2 rounded" onClick={() => showToast("Opening FAQ...", "info")}>
                    <span className="text-sm font-medium text-gray-700">Frequently Asked Questions</span>
                    <i className="fa-solid fa-chevron-right text-xs text-gray-400"></i>
                </div>
                <div className="flex justify-between items-center py-4 cursor-pointer hover:bg-gray-50 px-2 -mx-2 rounded" onClick={() => showToast("Opening Terms...", "info")}>
                    <span className="text-sm font-medium text-gray-700">Terms & Conditions</span>
                    <i className="fa-solid fa-chevron-right text-xs text-gray-400"></i>
                </div>
                <div className="flex justify-between items-center py-4 cursor-pointer hover:bg-gray-50 px-2 -mx-2 rounded" onClick={() => showToast("Opening Privacy...", "info")}>
                    <span className="text-sm font-medium text-gray-700">Privacy Policy</span>
                    <i className="fa-solid fa-chevron-right text-xs text-gray-400"></i>
                </div>
                <div className="flex justify-between items-center py-4 cursor-pointer hover:bg-gray-50 px-2 -mx-2 rounded" onClick={() => showToast("Opening Guidelines...", "info")}>
                    <span className="text-sm font-medium text-gray-700">Community Guidelines</span>
                    <i className="fa-solid fa-chevron-right text-xs text-gray-400"></i>
                </div>
            </div>
            <div className="mt-4 text-center">
                <p className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">Version 1.0.2</p>
            </div>
        </Card>
    );

    // 6. Role Management Section
    const renderRoleManagement = () => (
        <Card className="p-6 mb-6">
            <h3 className="text-lg font-bold font-display text-gray-900 mb-4">Role Management</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {/* Buyer Role */}
                <div 
                    onClick={() => handleRoleSwitch('buyer')}
                    className={`cursor-pointer rounded-xl p-4 border-2 transition-all flex flex-col items-center justify-center gap-2 ${currentRole === 'buyer' ? 'border-primary bg-primary/5' : 'border-gray-100 hover:border-gray-200'}`}
                >
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${currentRole === 'buyer' ? 'bg-primary text-white' : 'bg-gray-100 text-gray-400'}`}>
                        <i className="fa-solid fa-bag-shopping"></i>
                    </div>
                    <span className={`font-bold text-sm ${currentRole === 'buyer' ? 'text-primary' : 'text-gray-600'}`}>Buyer</span>
                    {currentRole === 'buyer' && <span className="text-[10px] font-bold bg-primary text-white px-2 py-0.5 rounded-full">Active</span>}
                </div>

                {/* Vendor Role */}
                <div 
                    onClick={() => {
                        if (currentUser.roles.includes('vendor')) handleRoleSwitch('vendor');
                        else navigate('/vendor/onboarding');
                    }}
                    className={`cursor-pointer rounded-xl p-4 border-2 transition-all flex flex-col items-center justify-center gap-2 ${currentRole === 'vendor' ? 'border-secondary bg-secondary/5' : 'border-gray-100 hover:border-gray-200'}`}
                >
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${currentRole === 'vendor' ? 'bg-secondary text-white' : 'bg-gray-100 text-gray-400'}`}>
                        <i className="fa-solid fa-store"></i>
                    </div>
                    <span className={`font-bold text-sm ${currentRole === 'vendor' ? 'text-secondary' : 'text-gray-600'}`}>Vendor</span>
                    {currentRole === 'vendor' ? (
                        <span className="text-[10px] font-bold bg-secondary text-white px-2 py-0.5 rounded-full">Active</span>
                    ) : !currentUser.roles.includes('vendor') && (
                        <span className="text-[10px] font-bold bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">Register</span>
                    )}
                </div>

                {/* Delivery Role */}
                <div 
                    onClick={() => {
                        if (currentUser.roles.includes('deliveryPerson')) handleRoleSwitch('deliveryPerson');
                        else setIsDeliveryRegOpen(true);
                    }}
                    className={`cursor-pointer rounded-xl p-4 border-2 transition-all flex flex-col items-center justify-center gap-2 ${currentRole === 'deliveryPerson' ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-200'}`}
                >
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${currentRole === 'deliveryPerson' ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-400'}`}>
                        <i className="fa-solid fa-motorcycle"></i>
                    </div>
                    <span className={`font-bold text-sm ${currentRole === 'deliveryPerson' ? 'text-blue-500' : 'text-gray-600'}`}>Rider</span>
                    {currentRole === 'deliveryPerson' ? (
                        <span className="text-[10px] font-bold bg-blue-500 text-white px-2 py-0.5 rounded-full">Active</span>
                    ) : !currentUser.roles.includes('deliveryPerson') && (
                        <span className="text-[10px] font-bold bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">Apply</span>
                    )}
                </div>
            </div>
        </Card>
    );

    return (
        <div className="min-h-screen bg-gray-50 pb-20">
            {/* Header */}
            <div className="bg-white border-b border-gray-100 sticky top-0 z-30">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
                    <div>
                         <h1 className="text-xl font-display font-bold text-gray-900">Profile</h1>
                         <p className="text-[10px] text-gray-400 font-medium tracking-wide">Where Buyers and Sellers Get <span className="text-primary">LYNQED</span>.</p>
                    </div>
                    {/* Desktop Shortcuts */}
                    <div className="hidden lg:flex items-center gap-4">
                        <Button variant="ghost" size="sm" icon="cart-shopping" onClick={() => navigate('/buyer/cart')}>Cart</Button>
                        <Button variant="ghost" size="sm" icon="box" onClick={() => navigate('/buyer/orders')}>Orders</Button>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Left Column (Main) */}
                    <div className="lg:col-span-2">
                        {renderUserInfo()}

                        <div className="mb-8">
                            {currentRole === 'buyer' && renderBuyerSection()}
                            {currentRole === 'vendor' && renderVendorSection()}
                            {currentRole === 'deliveryPerson' && renderDeliverySection()}
                        </div>

                        {renderRoleManagement()}

                        <Card className="p-6 mb-6">
                            <h3 className="text-lg font-bold font-display text-gray-900 mb-4">Settings</h3>
                            <div className="space-y-1 divide-y divide-gray-50">
                                <div className="flex justify-between items-center py-4">
                                    <span className="text-sm font-medium text-gray-700">Notification Preferences</span>
                                    <button className="text-xs font-bold text-primary hover:underline">Manage</button>
                                </div>
                                <div className="flex justify-between items-center py-4">
                                    <span className="text-sm font-medium text-gray-700">Theme Mode</span>
                                    <Toggle checked={theme === 'dark'} onChange={toggleTheme} label={theme === 'dark' ? 'Dark' : 'Light'} />
                                </div>
                                <div className="flex justify-between items-center py-4 pt-6">
                                    <button onClick={logout} className="text-sm font-bold text-gray-500 hover:text-gray-900 flex items-center gap-2">
                                        <i className="fa-solid fa-arrow-right-from-bracket"></i> Logout
                                    </button>
                                    <Button variant="danger" size="sm" onClick={() => setIsDeleteModalOpen(true)}>Delete Account</Button>
                                </div>
                            </div>
                        </Card>

                        {renderAppInfo()}
                    </div>

                    {/* Right Column (Desktop Shortcuts / Summary) */}
                    <div className="hidden lg:block lg:col-span-1 space-y-6">
                         <Card className="p-6 sticky top-24">
                             <h3 className="font-bold text-gray-900 mb-4">Quick Shortcuts</h3>
                             <div className="space-y-3">
                                 <Button fullWidth variant="secondary" icon="cart-shopping" className="justify-start" onClick={() => navigate('/buyer/cart')}>My Cart</Button>
                                 <Button fullWidth variant="secondary" icon="box" className="justify-start" onClick={() => navigate('/buyer/orders')}>My Orders</Button>
                                 <Button fullWidth variant="secondary" icon="bell" className="justify-start">Notifications</Button>
                             </div>
                         </Card>
                    </div>
                </div>
            </div>

            {/* --- MODALS --- */}

            {/* Delivery Registration */}
            <Modal isOpen={isDeliveryRegOpen} onClose={() => setIsDeliveryRegOpen(false)} title="Register as Delivery Personnel">
                 <form onSubmit={handleDeliverySubmit} className="space-y-4">
                     <Input label="Full Name" value={deliveryForm.fullName} onChange={e => setDeliveryForm({...deliveryForm, fullName: e.target.value})} />
                     <Input label="Phone Number" value={deliveryForm.phone} onChange={e => setDeliveryForm({...deliveryForm, phone: e.target.value})} placeholder="050..." type="tel" required />
                     <div>
                         <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 ml-1">Transport Type</label>
                         <select className="block w-full rounded-2xl border-transparent bg-gray-50 py-3 px-4 text-sm" value={deliveryForm.transportType} onChange={e => setDeliveryForm({...deliveryForm, transportType: e.target.value})}>
                             {['Bike', 'Motorbike', 'Car', 'Walking'].map(o => <option key={o} value={o}>{o}</option>)}
                         </select>
                     </div>
                     <Input label="Delivery Radius (km)" type="number" value={deliveryForm.radius} onChange={e => setDeliveryForm({...deliveryForm, radius: parseInt(e.target.value)})} placeholder="5" />
                     <div className="space-y-2">
                         <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider">Upload National ID (Front & Back)</label>
                         <div className="grid grid-cols-2 gap-3">
                             <div className="h-24 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center text-gray-400 cursor-pointer hover:border-primary hover:text-primary transition-colors">
                                 <i className="fa-solid fa-id-card mb-1"></i><span className="text-[10px] font-bold">Front</span>
                             </div>
                             <div className="h-24 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center text-gray-400 cursor-pointer hover:border-primary hover:text-primary transition-colors">
                                 <i className="fa-solid fa-id-card mb-1"></i><span className="text-[10px] font-bold">Back</span>
                             </div>
                         </div>
                     </div>
                     <div className="flex items-center gap-3 pt-2">
                         <input type="checkbox" id="terms" checked={deliveryForm.agreed} onChange={e => setDeliveryForm({...deliveryForm, agreed: e.target.checked})} className="w-4 h-4 text-primary rounded" />
                         <label htmlFor="terms" className="text-xs text-gray-600">I confirm my details are correct.</label>
                     </div>
                     <Button type="submit" fullWidth disabled={regStatus === 'submitting' || !deliveryForm.agreed}>{regStatus === 'submitting' ? 'Submitting...' : 'Submit Registration'}</Button>
                 </form>
            </Modal>

            {/* Order Tracking */}
            <Modal isOpen={!!trackingOrder} onClose={() => setTrackingOrder(null)} title="Order Details">
                {trackingOrder && <OrderTracking order={trackingOrder} onClose={() => setTrackingOrder(null)} />}
            </Modal>

            {/* Delete Account */}
            <Modal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} title="Delete Account">
                <div className="text-center p-4">
                    <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4 text-red-600 text-2xl"><i className="fa-solid fa-triangle-exclamation"></i></div>
                    <h3 className="text-lg font-bold text-gray-900 mb-2">Are you sure?</h3>
                    <p className="text-gray-500 text-sm mb-6">Delete my account and personal data. This action cannot be undone.</p>
                    <div className="flex gap-3"><Button variant="ghost" fullWidth onClick={() => setIsDeleteModalOpen(false)}>Cancel</Button><Button variant="danger" fullWidth onClick={handleDeleteAccount}>Delete Account</Button></div>
                </div>
            </Modal>

            {/* Payout */}
            <Modal isOpen={isPayoutModalOpen} onClose={() => setIsPayoutModalOpen(false)} title="Request Payout">
                 <div className="space-y-4">
                     <div className="bg-green-50 p-4 rounded-xl text-center"><p className="text-xs font-bold text-green-600 uppercase">Available Balance</p><h2 className="text-3xl font-bold text-gray-900">₵120.00</h2></div>
                     <Input label="Amount" placeholder="0.00" type="number" />
                     <div className="space-y-2"><label className="block text-xs font-bold text-gray-500 uppercase tracking-wider">Select Method</label>{['MTN MoMo', 'Vodafone Cash', 'AirtelTigo Cash', 'Bank Account'].map(m => (<div key={m} className="p-3 border border-gray-100 rounded-xl flex items-center justify-between cursor-pointer hover:bg-gray-50"><span className="text-sm font-medium">{m}</span><input type="radio" name="payout" /></div>))}</div>
                     <Button fullWidth onClick={() => { setIsPayoutModalOpen(false); showToast("Payout request processing.", "success"); }}>Request Payout</Button>
                 </div>
            </Modal>

            {/* Edit Profile */}
            <Modal isOpen={isEditProfileOpen} onClose={() => setIsEditProfileOpen(false)} title="Edit Profile">
                 <div className="space-y-4">
                     <div className="flex justify-center mb-4"><Avatar src={currentUser.avatarUrl} name={currentUser.name} size="xl" /></div>
                     <Input label="Full Name" defaultValue={currentUser.name} />
                     <Input label="Email" defaultValue={currentUser.email} disabled className="opacity-50" />
                     <Input label="Phone" defaultValue={currentUser.phoneNumber} />
                     <Button fullWidth onClick={() => { setIsEditProfileOpen(false); showToast("Profile updated successfully.", "success"); }}>Save Changes</Button>
                 </div>
            </Modal>

            {/* Contact Us */}
            <Modal isOpen={isContactOpen} onClose={() => setIsContactOpen(false)} title="Contact Us">
                <form onSubmit={handleContactSubmit} className="space-y-4">
                    <Input label="Full Name" value={contactForm.fullName} onChange={e => setContactForm({...contactForm, fullName: e.target.value})} required />
                    <Input label="Email" value={contactForm.email} onChange={e => setContactForm({...contactForm, email: e.target.value})} required type="email" />
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 ml-1">Message</label>
                        <textarea className="block w-full rounded-2xl border-transparent bg-white shadow-sm ring-1 ring-gray-100 py-3 px-4 text-gray-900 placeholder-gray-400 focus:border-primary focus:ring-2 focus:ring-primary/20 text-sm h-32" value={contactForm.message} onChange={e => setContactForm({...contactForm, message: e.target.value})} required></textarea>
                    </div>
                    <Button type="submit" fullWidth disabled={regStatus === 'submitting'}>{regStatus === 'submitting' ? 'Sending...' : 'Send Message'}</Button>
                </form>
            </Modal>

        </div>
    );
};

export const OrdersPage: React.FC = () => {
    const { orders, currentUser } = useApp();
    const navigate = useNavigate();
    const [trackingOrder, setTrackingOrder] = useState<Order | null>(null);

    const myOrders = useMemo(() => {
        if (!currentUser) return [];
        return orders.filter(o => o.buyerId === currentUser.id).sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    }, [orders, currentUser]);

    const formatDate = (dateStr: string) => new Date(dateStr).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

    return (
        <div className="min-h-screen bg-gray-50 pb-safe">
            <div className="bg-white p-4 shadow-sm sticky top-0 z-10 flex items-center gap-3">
                <button onClick={() => navigate(-1)}><i className="fa-solid fa-arrow-left"></i></button>
                <h1 className="text-xl font-bold font-display">My Orders</h1>
            </div>
            <div className="p-4 space-y-4">
                {myOrders.length === 0 ? <div className="text-center py-20 text-gray-400"><i className="fa-solid fa-box-open text-4xl mb-4 opacity-20"></i><p>No orders yet.</p><Button className="mt-4" onClick={() => navigate('/buyer/dashboard')}>Start Shopping</Button></div> : 
                    myOrders.map(order => (
                        <Card key={order.id} className="p-4" onClick={() => setTrackingOrder(order)}>
                             <div className="flex justify-between items-start mb-3 border-b border-gray-50 pb-2">
                                <div><span className="font-bold text-gray-900 block">Order #{order.id.slice(-5)}</span><span className="text-xs text-gray-500">{formatDate(order.createdAt)}</span></div>
                                <div className="text-right"><span className="block font-bold text-primary">₵{order.total.toFixed(2)}</span><Badge color={['delivered', 'completed'].includes(order.status) ? 'green' : 'blue'}>{order.status.replace('_', ' ')}</Badge></div>
                            </div>
                            <div className="space-y-2 mb-3">{order.items.map((item, idx) => (<div key={idx} className="flex justify-between text-sm"><span className="font-medium text-gray-700">{item.quantity}x {item.product.title}</span><span className="text-gray-500">₵{(item.product.price * item.quantity).toFixed(2)}</span></div>))}</div>
                            <div className="flex justify-between items-center pt-2 border-t border-gray-50 text-xs text-gray-500"><span>{order.items.length} Items</span><span>{order.deliveryOption === 'pickup' ? 'Pickup' : 'Delivery'}</span></div>
                        </Card>
                    ))
                }
            </div>
            <Modal isOpen={!!trackingOrder} onClose={() => setTrackingOrder(null)} title="Order Details">{trackingOrder && <OrderTracking order={trackingOrder} onClose={() => setTrackingOrder(null)} />}</Modal>
        </div>
    );
};

export const WishlistPage: React.FC = () => {
    const { products, favorites, toggleFavorite, addToCart, cart, removeFromCart, showToast } = useApp();
    const navigate = useNavigate();
    const wishlistItems = useMemo(() => products.filter(p => favorites.includes(p.id)), [products, favorites]);

    return (
        <div className="min-h-screen bg-gray-50 pb-safe">
            <div className="bg-white p-4 shadow-sm sticky top-0 z-10 flex items-center gap-3"><button onClick={() => navigate(-1)}><i className="fa-solid fa-arrow-left"></i></button><h1 className="text-xl font-bold font-display">My Wishlist</h1></div>
            <div className="p-4">
                {wishlistItems.length === 0 ? <div className="text-center py-20 text-gray-400"><i className="fa-regular fa-heart text-4xl mb-4 opacity-20"></i><p>Your wishlist is empty.</p><Button className="mt-4" onClick={() => navigate('/buyer/dashboard')}>Explore Products</Button></div> : 
                    <div className="grid grid-cols-2 gap-3">
                        {wishlistItems.map(product => {
                            const isInCart = cart.some(item => item.productId === product.id);
                            return (
                                <div key={product.id} className="bg-white rounded-2xl overflow-hidden shadow-card border border-gray-100 hover:shadow-xl transition-all duration-300 group relative flex flex-col h-full cursor-pointer" onClick={() => navigate(`/buyer/product/${product.id}`)}>
                                    <div className="aspect-square w-full relative overflow-hidden"><img src={product.images[0]} alt={product.title} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                                        <button className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/80 backdrop-blur-sm border border-gray-100 hover:border-red-100 text-red-500 flex items-center justify-center transition-colors shadow-sm active:scale-90" onClick={(e) => { e.stopPropagation(); toggleFavorite(product.id); }}><i className="fa-solid fa-heart text-xs"></i></button>
                                    </div>
                                    <div className="p-3 bg-white flex flex-col justify-between flex-grow relative z-10">
                                        <div><h3 className="text-sm text-gray-800 font-bold leading-tight line-clamp-2 mb-1">{product.title}</h3></div>
                                        <div className="flex items-center justify-between mt-2"><span className="text-lg font-extrabold text-gray-900">{product.currency}{product.price.toFixed(2)}</span>
                                            <button className={`w-8 h-8 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 group-btn ${product.stock === 0 ? 'bg-gray-300 cursor-not-allowed' : isInCart ? 'bg-green-500 hover:bg-red-500' : 'bg-black hover:bg-primary'}`} onClick={(e) => { e.stopPropagation(); if (product.stock > 0) { if (isInCart) { removeFromCart(product.id); showToast('Removed from Cart', 'info'); } else { addToCart(product); } } }} disabled={product.stock === 0}><i className={`fa-solid ${isInCart ? 'fa-check group-btn-hover:fa-trash' : 'fa-plus'} text-xs ${isInCart ? 'group-hover:hidden' : ''}`}></i>{isInCart && <i className="fa-solid fa-trash text-xs hidden group-hover:inline"></i>}</button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                }
            </div>
        </div>
    );
};
